const half = (u0, name, t1, unit) => L(`Величина $${name}$ уменьшается вдвое каждые ${t1} ${unit}: $${name}=${u0}\\cdot\\left(\\dfrac12\\right)^{t/${t1}}$.`, `$${name}$ шамасы әр ${t1} ${unit} сайын екі есе азаяды: $${name}=${u0}\\cdot\\left(\\dfrac12\\right)^{t/${t1}}$.`, `The quantity $${name}$ halves every ${t1} ${unit}: $${name}=${u0}\\cdot\\left(\\dfrac12\\right)^{t/${t1}}$.`);
const coolSetup = (Tc, T0, T1, t1) => [
  L(`<b>Обозначения.</b> $T(t)$ — температура через $t$ минут; температура среды $T_c=${Tc}^\\circ$.`, `<b>Белгілеулер.</b> $T(t)$ — $t$ минуттан кейінгі температура; орта температурасы $T_c=${Tc}^\\circ$.`, `<b>Notation.</b> $T(t)$ is the temperature after $t$ minutes; the surroundings are at $T_c=${Tc}^\\circ$.`),
  L(`<b>Уравнение.</b> Закон Ньютона: скорость остывания пропорциональна разности температур: $T'=-k(T-${Tc})$.`, `<b>Теңдеу.</b> Ньютон заңы: суу жылдамдығы температуралар айырмасына пропорционал: $T'=-k(T-${Tc})$.`, `<b>Equation.</b> Newton's law: the cooling rate is proportional to the temperature difference: $T'=-k(T-${Tc})$.`),
  L(`<b>Решаем.</b> Пусть $u=T-${Tc}$. Тогда $u'=-ku$; разделяем переменные: $\\dfrac{du}{u}=-k\\,dt$, $\\ln u=-kt+C_1$, $u=Ce^{-kt}$.`, `<b>Шешеміз.</b> $u=T-${Tc}$ болсын. Сонда $u'=-ku$; айнымалыларды ажыратамыз: $\\dfrac{du}{u}=-k\\,dt$, $\\ln u=-kt+C_1$, $u=Ce^{-kt}$.`, `<b>Solve.</b> Let $u=T-${Tc}$. Then $u'=-ku$; separate the variables: $\\dfrac{du}{u}=-k\\,dt$, $\\ln u=-kt+C_1$, $u=Ce^{-kt}$.`),
  L(`<b>Начальное условие.</b> При $t=0$: $u=${T0}-${Tc}=${T0 - Tc}$, значит $C=${T0 - Tc}$.`, `<b>Бастапқы шарт.</b> $t=0$ кезінде: $u=${T0}-${Tc}=${T0 - Tc}$, демек $C=${T0 - Tc}$.`, `<b>Initial condition.</b> At $t=0$: $u=${T0}-${Tc}=${T0 - Tc}$, so $C=${T0 - Tc}$.`),
  L(`<b>Находим $k$.</b> При $t=${t1}$: $u=${T1}-${Tc}=${T1 - Tc}$, то есть $e^{-${t1}k}=\\dfrac{${T1 - Tc}}{${T0 - Tc}}=\\dfrac12$. `, `<b>$k$-ны табамыз.</b> $t=${t1}$ кезінде: $u=${T1}-${Tc}=${T1 - Tc}$, яғни $e^{-${t1}k}=\\dfrac{${T1 - Tc}}{${T0 - Tc}}=\\dfrac12$. `, `<b>Find $k$.</b> At $t=${t1}$: $u=${T1}-${Tc}=${T1 - Tc}$, so $e^{-${t1}k}=\\dfrac{${T1 - Tc}}{${T0 - Tc}}=\\dfrac12$. `) + half(T0 - Tc, 'u', t1, L('мин', 'мин', 'min'))];
