GEN['asymptotes'].push(r => { const a = r.int(4, 12), b = r.int(2, 6);
  return { q: L(`При капельном введении концентрация лекарства в крови (мг/л) через $t$ часов описывается моделью $C(t)=\\dfrac{${a}t}{t+${b}}$. К какому значению стремится концентрация при длительном введении ($t\\to\\infty$)?`, `Тамшылатып енгізген кезде дәрінің қандағы концентрациясы (мг/л) $t$ сағаттан кейін $C(t)=\\dfrac{${a}t}{t+${b}}$ моделімен сипатталады. Ұзақ енгізгенде ($t\\to\\infty$) концентрация қандай мәнге ұмтылады?`, `During a drip the drug concentration in blood (mg/l) after $t$ hours follows $C(t)=\\dfrac{${a}t}{t+${b}}$. What value does it approach in the long run ($t\\to\\infty$)?`), a, lvl: 1, unit: L('мг/л', 'мг/л', 'mg/l'),
    hint: L('Это горизонтальная асимптота графика $C(t)$.', 'Бұл — $C(t)$ графигінің горизонталь асимптотасы.', 'This is the horizontal asymptote of $C(t)$.'),
    steps: [L('<b>Перевод на язык математики.</b> «К чему стремится при $t\\to\\infty$» — это предел на бесконечности, то есть горизонтальная асимптота.', '<b>Математика тіліне аудару.</b> «$t\\to\\infty$ кезінде неге ұмтылады» — шексіздіктегі шек, яғни горизонталь асимптота.', '<b>Translate into maths.</b> "What it approaches as $t\\to\\infty$" is a limit at infinity, i.e. a horizontal asymptote.'),
      L('<b>Тип.</b> Неопределённость $\\frac\\infty\\infty$: делим числитель и знаменатель на $t$.', '<b>Түрі.</b> $\\frac\\infty\\infty$ анықталмағандығы: алымы мен бөлімін $t$-ға бөлеміз.', '<b>Type.</b> The form $\\frac\\infty\\infty$: divide the numerator and denominator by $t$.'),
      `$$\\lim_{t\\to\\infty}\\frac{${a}t}{t+${b}}=\\lim_{t\\to\\infty}\\frac{${a}}{1+\\frac{${b}}{t}}=\\frac{${a}}{1+0}=${a}$$`,
      L(`<b>Смысл.</b> Концентрация растёт, но не превысит ${a} мг/л — это «потолок» модели.`, `<b>Мағынасы.</b> Концентрация өседі, бірақ ${a} мг/л-ден аспайды — бұл модельдің «төбесі».`, `<b>Meaning.</b> The concentration rises but never exceeds ${a} mg/l — the model's ceiling.`)] }; });
GEN['derivative-def'].push(r => { const b = r.int(2, 9), t1 = r.int(1, 3), t2 = t1 + r.int(1, 3), N = t => t * t + b * t, ans = (N(t2) - N(t1)) / (t2 - t1);
  return { q: L(`Число просмотров видео (в тысячах) через $t$ часов после публикации: $N(t)=t^2+${b}t$. Найдите среднюю скорость роста просмотров на промежутке от $t=${t1}$ до $t=${t2}$ ч (тыс. в час).`, `Видео жарияланғаннан $t$ сағат өткендегі қаралым саны (мыңмен): $N(t)=t^2+${b}t$. $t=${t1}$-ден $t=${t2}$ сағатқа дейінгі аралықтағы қаралымның орташа өсу жылдамдығын табыңыз (мың/сағ).`, `The number of views of a video (in thousands) $t$ hours after posting is $N(t)=t^2+${b}t$. Find the average growth rate from $t=${t1}$ to $t=${t2}$ h (thousand per hour).`), a: ans, lvl: 1,
    hint: L('Средняя скорость — это $\\dfrac{\\Delta N}{\\Delta t}$.', 'Орташа жылдамдық — $\\dfrac{\\Delta N}{\\Delta t}$.', 'The average rate is $\\dfrac{\\Delta N}{\\Delta t}$.'),
    steps: [L('<b>Формула.</b> Средняя скорость изменения $=\\dfrac{\\Delta N}{\\Delta t}=\\dfrac{N(t_2)-N(t_1)}{t_2-t_1}$.', '<b>Формула.</b> Орташа өзгеру жылдамдығы $=\\dfrac{\\Delta N}{\\Delta t}=\\dfrac{N(t_2)-N(t_1)}{t_2-t_1}$.', '<b>Formula.</b> Average rate of change $=\\dfrac{\\Delta N}{\\Delta t}=\\dfrac{N(t_2)-N(t_1)}{t_2-t_1}$.'),
      L(`<b>Значения функции.</b> $N(${t1})=${t1 * t1}+${b * t1}=${N(t1)}$; $N(${t2})=${t2 * t2}+${b * t2}=${N(t2)}$.`, `<b>Функция мәндері.</b> $N(${t1})=${t1 * t1}+${b * t1}=${N(t1)}$; $N(${t2})=${t2 * t2}+${b * t2}=${N(t2)}$.`, `<b>Function values.</b> $N(${t1})=${t1 * t1}+${b * t1}=${N(t1)}$; $N(${t2})=${t2 * t2}+${b * t2}=${N(t2)}$.`),
      L(`<b>Приращения.</b> $\\Delta N=${N(t2)}-${N(t1)}=${N(t2) - N(t1)}$, $\\Delta t=${t2}-${t1}=${t2 - t1}$.`, `<b>Өсімшелер.</b> $\\Delta N=${N(t2)}-${N(t1)}=${N(t2) - N(t1)}$, $\\Delta t=${t2}-${t1}=${t2 - t1}$.`, `<b>Increments.</b> $\\Delta N=${N(t2)}-${N(t1)}=${N(t2) - N(t1)}$, $\\Delta t=${t2}-${t1}=${t2 - t1}$.`),
      L(`<b>Делим.</b> $\\dfrac{${N(t2) - N(t1)}}{${t2 - t1}}=${nt(ans)}$ тыс. просмотров в час. Мгновенная скорость $N'(t)=2t+${b}$ в середине промежутка даёт то же число — для квадратичной функции так всегда.`, `<b>Бөлеміз.</b> $\\dfrac{${N(t2) - N(t1)}}{${t2 - t1}}=${nt(ans)}$ мың қаралым/сағ. Аралықтың ортасындағы лездік жылдамдық $N'(t)=2t+${b}$ дәл сол санды береді — квадраттық функция үшін әрқашан солай.`, `<b>Divide.</b> $\\dfrac{${N(t2) - N(t1)}}{${t2 - t1}}=${nt(ans)}$ thousand views per hour. The instantaneous rate $N'(t)=2t+${b}$ at the midpoint gives the same number — always true for a quadratic.`)] }; });
GEN['derivative-meaning'].push(r => { const a = r.int(1, 4), b = r.int(1, 6), t1 = r.int(2, 5), ans = 2 * a * t1 + b;
  return { q: L(`Заряд, прошедший через проводник за время $t$ (в секундах), равен $q(t)=${co(a, 't^2')}+${co(b, 't')}$ Кл. Найдите силу тока в момент $t=${t1}$ с. (Сила тока — скорость изменения заряда.)`, `Өткізгіш арқылы $t$ уақытта (секундпен) өткен заряд $q(t)=${co(a, 't^2')}+${co(b, 't')}$ Кл. $t=${t1}$ с мезетіндегі ток күшін табыңыз. (Ток күші — зарядтың өзгеру жылдамдығы.)`, `The charge that has passed through a conductor by time $t$ (seconds) is $q(t)=${co(a, 't^2')}+${co(b, 't')}$ C. Find the current at $t=${t1}$ s. (Current is the rate of change of charge.)`), a: ans, lvl: 1, unit: L('А', 'А', 'A'),
    hint: L('$I(t)=q\'(t)$.', '$I(t)=q\'(t)$.', '$I(t)=q\'(t)$.'),
    steps: [L('<b>Физический смысл производной.</b> Скорость изменения любой величины — её производная по времени: $I(t)=q\'(t)$.', '<b>Туындының физикалық мағынасы.</b> Кез келген шаманың өзгеру жылдамдығы — оның уақыт бойынша туындысы: $I(t)=q\'(t)$.', '<b>Physical meaning of the derivative.</b> The rate of change of any quantity is its time derivative: $I(t)=q\'(t)$.'),
      L(`<b>Дифференцируем.</b> $q'(t)=${co(2 * a, 't')}+${b}$.`, `<b>Дифференциалдаймыз.</b> $q'(t)=${co(2 * a, 't')}+${b}$.`, `<b>Differentiate.</b> $q'(t)=${co(2 * a, 't')}+${b}$.`),
      L(`<b>Подставляем.</b> $I(${t1})=${2 * a}\\cdot${t1}+${b}=${ans}$ А.`, `<b>Қоямыз.</b> $I(${t1})=${2 * a}\\cdot${t1}+${b}=${ans}$ А.`, `<b>Substitute.</b> $I(${t1})=${2 * a}\\cdot${t1}+${b}=${ans}$ A.`)] }; });
GEN['monotonicity'].push(r => { const a = r.int(11, 16), c = r.int(-8, 4);
  return { q: L(`Температура воздуха в течение суток ($0\\le t\\le24$, $t$ — время в часах) менялась по закону $T(t)=-\\dfrac{t^2}{10}+${dec(a / 5)}t${sg(c)}$ (°C). До какого часа температура повышалась?`, `Тәулік бойы ауа температурасы ($0\\le t\\le24$, $t$ — сағатпен уақыт) $T(t)=-\\dfrac{t^2}{10}+${dec(a / 5)}t${sg(c)}$ (°C) заңымен өзгерді. Температура нешінші сағатқа дейін көтерілді?`, `During a day ($0\\le t\\le24$, $t$ in hours) the air temperature followed $T(t)=-\\dfrac{t^2}{10}+${dec(a / 5)}t${sg(c)}$ (°C). Until what hour was it rising?`), a, lvl: 2, unit: L('ч', 'сағ', 'h'),
    hint: L('Температура растёт там, где $T\'(t)>0$.', 'Температура $T\'(t)>0$ болатын жерде өседі.', 'The temperature rises where $T\'(t)>0$.'),
    steps: [L('<b>Признак возрастания.</b> Функция возрастает на промежутке, где её производная положительна.', '<b>Өсу белгісі.</b> Функция туындысы оң болатын аралықта өседі.', '<b>Test for increase.</b> A function increases where its derivative is positive.'),
      L(`<b>Производная.</b> $T'(t)=-\\dfrac{t}{5}+${dec(a / 5)}$.`, `<b>Туынды.</b> $T'(t)=-\\dfrac{t}{5}+${dec(a / 5)}$.`, `<b>Derivative.</b> $T'(t)=-\\dfrac{t}{5}+${dec(a / 5)}$.`),
      L(`<b>Неравенство.</b> $-\\dfrac t5+${dec(a / 5)}>0\\iff t<${a}$.`, `<b>Теңсіздік.</b> $-\\dfrac t5+${dec(a / 5)}>0\\iff t<${a}$.`, `<b>Inequality.</b> $-\\dfrac t5+${dec(a / 5)}>0\\iff t<${a}$.`),
      L(`<b>Ответ.</b> Температура росла до ${a} часов, а потом понижалась; в ${a}:00 был максимум.`, `<b>Жауап.</b> Температура сағат ${a}-ге дейін көтеріліп, содан кейін төмендеді; ${a}:00-де максимум болды.`, `<b>Answer.</b> The temperature rose until ${a} o'clock and then fell; the maximum was at ${a}:00.`)] }; });
GEN['extrema'].push(r => { const a = r.int(3, 9), c = r.int(2, 8);
  return { q: L(`Прибыль мастерской (тыс. тенге в день) при выпуске $x$ изделий: $P(x)=-x^2+${2 * a}x-${c}$. Какую наибольшую прибыль можно получить?`, `Шеберхананың $x$ бұйым шығарғандағы пайдасы (күніне мың теңге): $P(x)=-x^2+${2 * a}x-${c}$. Ең көп дегенде қандай пайда алуға болады?`, `A workshop's profit (thousand tenge a day) when making $x$ items is $P(x)=-x^2+${2 * a}x-${c}$. What is the greatest possible profit?`), a: a * a - c, lvl: 2,
    hint: L('Найдите точку максимума: $P\'(x)=0$.', 'Максимум нүктесін табыңыз: $P\'(x)=0$.', 'Find the maximum point: $P\'(x)=0$.'),
    steps: [L(`<b>Производная.</b> $P'(x)=-2x+${2 * a}$.`, `<b>Туынды.</b> $P'(x)=-2x+${2 * a}$.`, `<b>Derivative.</b> $P'(x)=-2x+${2 * a}$.`),
      L(`<b>Критическая точка.</b> $-2x+${2 * a}=0$, $x=${a}$.`, `<b>Сындық нүкте.</b> $-2x+${2 * a}=0$, $x=${a}$.`, `<b>Critical point.</b> $-2x+${2 * a}=0$, $x=${a}$.`),
      L(`<b>Знаки.</b> При $x<${a}$ $P'>0$ (прибыль растёт), при $x>${a}$ $P'<0$ (падает): «$+$» сменился на «$-$» — максимум.`, `<b>Таңбалар.</b> $x<${a}$ болғанда $P'>0$ (пайда өседі), $x>${a}$ болғанда $P'<0$ (кемиді): «$+$» «$-$»-ке ауысты — максимум.`, `<b>Signs.</b> For $x<${a}$, $P'>0$ (profit grows); for $x>${a}$, $P'<0$ (falls): plus to minus — a maximum.`),
      L(`<b>Значение.</b> $P(${a})=-${a * a}+${2 * a * a}-${c}=${a * a - c}$ тыс. тенге.`, `<b>Мәні.</b> $P(${a})=-${a * a}+${2 * a * a}-${c}=${a * a - c}$ мың теңге.`, `<b>Value.</b> $P(${a})=-${a * a}+${2 * a * a}-${c}=${a * a - c}$ thousand tenge.`),
      L('<b>Смысл.</b> Выпускать больше невыгодно: растут расходы, и каждое новое изделие приносит убыток.', '<b>Мағынасы.</b> Одан көп шығару тиімсіз: шығын өседі де, әрбір жаңа бұйым зиян әкеледі.', '<b>Meaning.</b> Making more does not pay: costs grow and each extra item brings a loss.')] }; });
GEN['convexity'].push(r => { const a = r.int(3, 8);
  return { q: L(`Число заболевших во время эпидемии описывается функцией $N(t)=-t^3+${3 * a}t^2$ ($0\\le t\\le${2 * a}$, $t$ — дни). В какой день скорость распространения болезни была наибольшей?`, `Індет кезіндегі ауырғандар саны $N(t)=-t^3+${3 * a}t^2$ функциясымен сипатталады ($0\\le t\\le${2 * a}$, $t$ — күндер). Аурудың таралу жылдамдығы қай күні ең жоғары болды?`, `The number of people infected during an epidemic is $N(t)=-t^3+${3 * a}t^2$ ($0\\le t\\le${2 * a}$, $t$ in days). On which day was the disease spreading fastest?`), a, lvl: 3,
    hint: L('Скорость — это $N\'(t)$. Она наибольшая там, где её производная $N\'\'(t)$ меняет знак с «+» на «−», то есть в точке перегиба.', 'Жылдамдық — $N\'(t)$. Ол өзінің туындысы $N\'\'(t)$ таңбасын «+»-тен «−»-ке өзгертетін жерде, яғни иілу нүктесінде ең үлкен.', 'The speed is $N\'(t)$. It is greatest where its derivative $N\'\'(t)$ changes from plus to minus — at the inflection point.'),
    steps: [L(`<b>Скорость распространения.</b> $v(t)=N'(t)=-3t^2+${6 * a}t$.`, `<b>Таралу жылдамдығы.</b> $v(t)=N'(t)=-3t^2+${6 * a}t$.`, `<b>Spreading speed.</b> $v(t)=N'(t)=-3t^2+${6 * a}t$.`),
      L(`<b>Ищем максимум скорости.</b> $v'(t)=N''(t)=-6t+${6 * a}$.`, `<b>Жылдамдықтың максимумын іздейміз.</b> $v'(t)=N''(t)=-6t+${6 * a}$.`, `<b>Look for the maximum of the speed.</b> $v'(t)=N''(t)=-6t+${6 * a}$.`),
      L(`<b>Уравнение.</b> $-6t+${6 * a}=0$, $t=${a}$.`, `<b>Теңдеу.</b> $-6t+${6 * a}=0$, $t=${a}$.`, `<b>Equation.</b> $-6t+${6 * a}=0$, $t=${a}$.`),
      L(`<b>Знаки.</b> До $t=${a}$ $N''>0$: скорость растёт, график выпуклый вниз. После — $N''<0$: скорость падает. Значит, $t=${a}$ — точка перегиба графика $N(t)$ и момент наибольшей скорости.`, `<b>Таңбалар.</b> $t=${a}$-ға дейін $N''>0$: жылдамдық өседі, график төмен дөңес. Одан кейін $N''<0$: жылдамдық кемиді. Демек, $t=${a}$ — $N(t)$ графигінің иілу нүктесі және жылдамдық ең үлкен мезет.`, `<b>Signs.</b> Before $t=${a}$, $N''>0$: the speed grows, the graph is convex down. After it $N''<0$: the speed falls. So $t=${a}$ is the inflection point of $N(t)$ and the moment of greatest speed.`),
      L('<b>Смысл.</b> Именно точку перегиба называют «переломом» эпидемии: заболевших ещё становится больше, но прирост уже замедляется.', '<b>Мағынасы.</b> Індеттің «бетбұрысы» деп дәл осы иілу нүктесін айтады: ауырғандар әлі көбейіп жатыр, бірақ өсім баяулай бастады.', '<b>Meaning.</b> The inflection point is what people call the "turning point" of an epidemic: cases still rise, but the growth is already slowing.')] }; });
GEN['max-min'].push(r => { const Lf = r.pick([40, 60, 80, 100, 120]), x = Lf / 4, ans = Lf * Lf / 8;
  return { q: L(`Фермер хочет огородить прямоугольный загон, примыкающий к стене сарая (со стороны стены забор не нужен). У него ${Lf} м сетки. Какую наибольшую площадь может иметь загон?`, `Фермер қора қабырғасына жанасатын тіктөртбұрышты қоршау жасағысы келеді (қабырға жағына қоршау керек емес). Оның ${Lf} м торы бар. Қоршаудың ауданы ең көп дегенде қандай болуы мүмкін?`, `A farmer wants a rectangular pen against a barn wall (no fence is needed along the wall). He has ${Lf} m of fencing. What is the largest possible area of the pen?`), a: ans, lvl: 3, unit: L('м²', 'м²', 'm²'),
    hint: L(`Пусть $x$ — сторона, перпендикулярная стене. Тогда вторая сторона $${Lf}-2x$.`, `$x$ — қабырғаға перпендикуляр жағы болсын. Сонда екінші жағы $${Lf}-2x$.`, `Let $x$ be the side perpendicular to the wall. Then the other side is $${Lf}-2x$.`),
    steps: [L(`<b>Вводим переменную.</b> $x$ — сторона, перпендикулярная стене (таких сторон две). На сторону вдоль стены остаётся $${Lf}-2x$. Ограничения: $0<x<${Lf / 2}$.`, `<b>Айнымалы енгіземіз.</b> $x$ — қабырғаға перпендикуляр жағы (ондай жақ екеу). Қабырға бойындағы жаққа $${Lf}-2x$ қалады. Шектеулер: $0<x<${Lf / 2}$.`, `<b>Introduce a variable.</b> $x$ is the side perpendicular to the wall (there are two). The side along the wall gets $${Lf}-2x$. Constraints: $0<x<${Lf / 2}$.`),
      L(`<b>Целевая функция.</b> $S(x)=x(${Lf}-2x)=${Lf}x-2x^2$.`, `<b>Мақсат функциясы.</b> $S(x)=x(${Lf}-2x)=${Lf}x-2x^2$.`, `<b>Objective function.</b> $S(x)=x(${Lf}-2x)=${Lf}x-2x^2$.`),
      L(`<b>Производная.</b> $S'(x)=${Lf}-4x$; $S'=0$ при $x=${x}$.`, `<b>Туынды.</b> $S'(x)=${Lf}-4x$; $x=${x}$ кезінде $S'=0$.`, `<b>Derivative.</b> $S'(x)=${Lf}-4x$; $S'=0$ at $x=${x}$.`),
      L(`<b>Проверка.</b> Слева от $${x}$ $S'>0$, справа $S'<0$ — максимум. На концах промежутка площадь равна нулю.`, `<b>Тексеру.</b> $${x}$-тің сол жағында $S'>0$, оң жағында $S'<0$ — максимум. Аралықтың шеттерінде аудан нөлге тең.`, `<b>Check.</b> Left of $${x}$, $S'>0$; right of it $S'<0$ — a maximum. At the ends of the interval the area is zero.`),
      L(`<b>Ответ.</b> Стороны $${x}$ м и $${Lf - 2 * x}$ м, площадь $S=${x}\\cdot${Lf - 2 * x}=${ans}$ м². Сторона вдоль стены вдвое длиннее.`, `<b>Жауап.</b> Қабырғалары $${x}$ м және $${Lf - 2 * x}$ м, ауданы $S=${x}\\cdot${Lf - 2 * x}=${ans}$ м². Қабырға бойындағы жағы екі есе ұзын.`, `<b>Answer.</b> Sides $${x}$ m and $${Lf - 2 * x}$ m, area $S=${x}\\cdot${Lf - 2 * x}=${ans}$ m². The side along the wall is twice as long.`)] }; });
GEN['antiderivative'].push(r => { const a = 2 * r.int(1, 4), b = r.int(1, 6), s0 = r.int(2, 10), t1 = r.int(2, 4), ans = a / 2 * t1 * t1 + b * t1 + s0;
  return { q: L(`Велосипедист движется по прямой со скоростью $v(t)=${a}t+${b}$ м/с. В момент $t=0$ он находился на отметке $${s0}$ м. На какой отметке он будет в момент $t=${t1}$ с?`, `Велосипедші түзу бойымен $v(t)=${a}t+${b}$ м/с жылдамдықпен қозғалады. $t=0$ мезетінде ол $${s0}$ м белгісінде болды. $t=${t1}$ с мезетінде ол қай белгіде болады?`, `A cyclist rides along a straight line at $v(t)=${a}t+${b}$ m/s. At $t=0$ he is at the $${s0}$ m mark. At which mark is he at $t=${t1}$ s?`), a: ans, lvl: 2, unit: L('м', 'м', 'm'),
    hint: L('Координата — первообразная скорости; константу найдите из условия при $t=0$.', 'Координата — жылдамдықтың алғашқы функциясы; тұрақтыны $t=0$ шартынан табыңыз.', 'Position is an antiderivative of speed; find the constant from the condition at $t=0$.'),
    steps: [L('<b>Связь.</b> $v(t)=s\'(t)$, значит $s(t)$ — первообразная для $v(t)$.', '<b>Байланыс.</b> $v(t)=s\'(t)$, демек $s(t)$ — $v(t)$ үшін алғашқы функция.', '<b>Link.</b> $v(t)=s\'(t)$, so $s(t)$ is an antiderivative of $v(t)$.'),
      L(`<b>Общий вид.</b> $s(t)=${co(a / 2, 't^2')}+${b}t+C$.`, `<b>Жалпы түрі.</b> $s(t)=${co(a / 2, 't^2')}+${b}t+C$.`, `<b>General form.</b> $s(t)=${co(a / 2, 't^2')}+${b}t+C$.`),
      L(`<b>Находим $C$.</b> $s(0)=C=${s0}$.`, `<b>$C$-ны табамыз.</b> $s(0)=C=${s0}$.`, `<b>Find $C$.</b> $s(0)=C=${s0}$.`),
      L(`<b>Подставляем.</b> $s(${t1})=${a / 2}\\cdot${t1 * t1}+${b}\\cdot${t1}+${s0}=${ans}$ м.`, `<b>Қоямыз.</b> $s(${t1})=${a / 2}\\cdot${t1 * t1}+${b}\\cdot${t1}+${s0}=${ans}$ м.`, `<b>Substitute.</b> $s(${t1})=${a / 2}\\cdot${t1 * t1}+${b}\\cdot${t1}+${s0}=${ans}$ m.`)] }; });
GEN['definite-integral'].push(r => { const a = r.int(2, 8), b = 2 * r.int(1, 3), T = r.int(2, 5), ans = a * T + b / 2 * T * T;
  return { q: L(`Вода поступает в бассейн со скоростью $r(t)=${a}+${b}t$ литров в минуту ($t$ — минуты от начала). Сколько литров воды поступит за первые ${T} минут?`, `Бассейнге су $r(t)=${a}+${b}t$ литр/мин жылдамдықпен құйылады ($t$ — басынан бергі минуттар). Алғашқы ${T} минутта неше литр су құйылады?`, `Water flows into a pool at $r(t)=${a}+${b}t$ litres per minute ($t$ is minutes from the start). How many litres arrive in the first ${T} minutes?`), a: ans, lvl: 2, unit: L('л', 'л', 'l'),
    hint: L('Накопленное количество — интеграл от скорости поступления.', 'Жиналған мөлшер — құйылу жылдамдығының интегралы.', 'The accumulated amount is the integral of the inflow rate.'),
    steps: [L(`<b>Модель.</b> За малое время $dt$ поступает $r(t)\\,dt$ литров. Всё вместе — интеграл: $V=\\int_0^{${T}}r(t)\\,dt$.`, `<b>Модель.</b> Аз $dt$ уақытта $r(t)\\,dt$ литр құйылады. Барлығы — интеграл: $V=\\int_0^{${T}}r(t)\\,dt$.`, `<b>Model.</b> In a short time $dt$, $r(t)\\,dt$ litres arrive. The total is an integral: $V=\\int_0^{${T}}r(t)\\,dt$.`),
      L(`<b>Первообразная.</b> $F(t)=${a}t+${co(b / 2, 't^2')}$.`, `<b>Алғашқы функция.</b> $F(t)=${a}t+${co(b / 2, 't^2')}$.`, `<b>Antiderivative.</b> $F(t)=${a}t+${co(b / 2, 't^2')}$.`),
      L(`<b>Формула Ньютона — Лейбница.</b> $V=F(${T})-F(0)=${a}\\cdot${T}+${b / 2}\\cdot${T * T}-0=${ans}$ л.`, `<b>Ньютон — Лейбниц формуласы.</b> $V=F(${T})-F(0)=${a}\\cdot${T}+${b / 2}\\cdot${T * T}-0=${ans}$ л.`, `<b>Newton–Leibniz formula.</b> $V=F(${T})-F(0)=${a}\\cdot${T}+${b / 2}\\cdot${T * T}-0=${ans}$ l.`),
      L(`<b>Проверка геометрией.</b> Под графиком $r(t)$ — трапеция с основаниями $${a}$ и $${a + b * T}$ и высотой $${T}$: $\\dfrac{${a}+${a + b * T}}{2}\\cdot${T}=${ans}$.`, `<b>Геометриямен тексеру.</b> $r(t)$ графигінің астында — табандары $${a}$ және $${a + b * T}$, биіктігі $${T}$ трапеция: $\\dfrac{${a}+${a + b * T}}{2}\\cdot${T}=${ans}$.`, `<b>Geometric check.</b> Under the graph of $r(t)$ is a trapezium with bases $${a}$ and $${a + b * T}$ and height $${T}$: $\\dfrac{${a}+${a + b * T}}{2}\\cdot${T}=${ans}$.`)] }; });
GEN['area'].push(r => { const w = r.pick([3, 6]), h = r.pick([2, 4, 5, 8]), ans = 4 * w * h / 3;
  return { q: L(`Арка ворот имеет форму параболы шириной ${2 * w} м у основания и высотой ${h} м: $y=${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)$. Сколько квадратных метров фанеры нужно, чтобы закрыть проём арки?`, `Қақпа аркасы табанындағы ені ${2 * w} м, биіктігі ${h} м парабола пішінді: $y=${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)$. Арка ойығын жабу үшін неше шаршы метр фанера керек?`, `A gate arch is a parabola ${2 * w} m wide at the base and ${h} m high: $y=${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)$. How many square metres of plywood are needed to cover the opening?`), a: ans, lvl: 3, unit: L('м²', 'м²', 'm²'),
    hint: L(`Площадь под параболой от $-${w}$ до $${w}$; воспользуйтесь симметрией.`, `$-${w}$-ден $${w}$-ге дейінгі парабола астындағы аудан; симметрияны пайдаланыңыз.`, `The area under the parabola from $-${w}$ to $${w}$; use symmetry.`),
    steps: [L(`<b>Пределы.</b> Парабола пересекает землю ($y=0$) при $x=\\pm${w}$.`, `<b>Шектер.</b> Парабола жерді ($y=0$) $x=\\pm${w}$ кезінде қияды.`, `<b>Limits.</b> The parabola meets the ground ($y=0$) at $x=\\pm${w}$.`),
      L(`<b>Интеграл.</b> $S=\\int_{-${w}}^{${w}}${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)dx$. Функция чётная, поэтому $S=2\\int_0^{${w}}\\ldots dx$.`, `<b>Интеграл.</b> $S=\\int_{-${w}}^{${w}}${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)dx$. Функция жұп, сондықтан $S=2\\int_0^{${w}}\\ldots dx$.`, `<b>Integral.</b> $S=\\int_{-${w}}^{${w}}${h}\\left(1-\\dfrac{x^2}{${w * w}}\\right)dx$. The function is even, so $S=2\\int_0^{${w}}\\ldots dx$.`),
      L(`<b>Первообразная.</b> $F(x)=${h}\\left(x-\\dfrac{x^3}{${3 * w * w}}\\right)$.`, `<b>Алғашқы функция.</b> $F(x)=${h}\\left(x-\\dfrac{x^3}{${3 * w * w}}\\right)$.`, `<b>Antiderivative.</b> $F(x)=${h}\\left(x-\\dfrac{x^3}{${3 * w * w}}\\right)$.`),
      L(`<b>Считаем.</b> $F(${w})=${h}\\left(${w}-\\dfrac{${w ** 3}}{${3 * w * w}}\\right)=${h}\\cdot${nt(2 * w / 3)}=${nt(2 * w * h / 3)}$; $S=2\\cdot${nt(2 * w * h / 3)}=${nt(ans)}$ м².`, `<b>Есептейміз.</b> $F(${w})=${h}\\left(${w}-\\dfrac{${w ** 3}}{${3 * w * w}}\\right)=${h}\\cdot${nt(2 * w / 3)}=${nt(2 * w * h / 3)}$; $S=2\\cdot${nt(2 * w * h / 3)}=${nt(ans)}$ м².`, `<b>Compute.</b> $F(${w})=${h}\\left(${w}-\\dfrac{${w ** 3}}{${3 * w * w}}\\right)=${h}\\cdot${nt(2 * w / 3)}=${nt(2 * w * h / 3)}$; $S=2\\cdot${nt(2 * w * h / 3)}=${nt(ans)}$ m².`),
      L('<b>Факт.</b> Ещё Архимед знал: площадь параболического сегмента составляет $\\dfrac23$ площади описанного прямоугольника.', '<b>Дерек.</b> Архимедтің өзі білген: парабола сегментінің ауданы сырттай сызылған тіктөртбұрыш ауданының $\\dfrac23$ бөлігіне тең.', '<b>Fact.</b> Archimedes already knew: a parabolic segment has $\\dfrac23$ of the area of the circumscribed rectangle.')] }; });
